#!/usr/bin/env Rscript
#
# Build-time tool (NOT part of the Shiny app bundle). Generates the gene-position
# and gene-identity reference (gene_positions.rds) that the output_explorer_embed
# app bundles for the Molecular Associations per-locus layout AND for harmonising
# gene identity across analyses (see R/utils_data.R harmonise_genes()).
#
# It reads the pipeline's authoritative biomart gene table (generated by
# pipeline/scripts/download_biomart.R, stored under {resdir}/data/biomart/), which
# is large and machine-specific, so this script deliberately lives OUTSIDE the app
# directory to keep it out of the deployment bundle.
#
# Re-run from the repo root whenever the biomart reference is refreshed:
#   Rscript pipeline/scripts/make_shiny_gene_positions.R \
#     {resdir}/data/biomart/biomart_genes_grch37.tsv \
#     pipeline/shiny_apps/output_explorer_embed/data/gene_positions.rds
#
# Output: a named list
#   by_symbol   external_gene_name -> (ID, CHR, BP)    position maps, BP = gene
#   by_synonym  external_synonym   -> (ID, CHR, BP)    midpoint, autosomes 1-22
#   by_ensembl  ensembl_gene_id    -> (ID, CHR, BP)    only (legacy; unchanged)
#   canonical   one row per ensembl_gene_id:
#               ensembl_gene_id, symbol, gene_biotype, CHR, BP
#   sym2id      named vector external_gene_name -> ensembl_gene_id
#   syn2id      named vector external_synonym   -> ensembl_gene_id
#
# canonical/sym2id/syn2id are built from the FULL table (incl. X/Y and patch
# contigs) so every gene has an identity even when it has no autosomal position
# (CHR/BP are then NA). When a symbol/synonym maps to several ensembl ids, ONE is
# chosen deterministically by: (1) standard contig (1-22/X/Y) before patch/scaffold;
# (2) a placed integer CHR before none; (3) gene_biotype == "protein_coding" first
# (a no-op until the biomart table carries gene_biotype); (4) lowest ensembl id
# lexicographically. gene_biotype is NA throughout if the input TSV predates the
# download_biomart.R change that adds it.

suppressMessages(library(data.table))

args <- commandArgs(trailingOnly = TRUE)
in_tsv <- if (length(args) >= 1) args[1] else
  "/cephfs/volumes/hpc_data_prj/neurohackpain/47452046-c6ec-4387-999a-e1d08d957104/GenoDisc/pipeline_resources/data/biomart/biomart_genes_grch37.tsv"
out_rds <- if (length(args) >= 2) args[2] else
  "pipeline/shiny_apps/output_explorer_embed/data/gene_positions.rds"

bm_full <- fread(in_tsv, na.strings = c("", "NA"))
if (!"gene_biotype" %in% names(bm_full)) bm_full[, gene_biotype := NA_character_]

# Interim biotype source: if the genes TSV predates the gene_biotype column
# (added by download_biomart.R), borrow biotype from the sibling
# gene_locations.tsv (keyed by symbol; lossy for colliding symbols). This is
# superseded automatically once biomart_genes_grch37.tsv carries gene_biotype.
if (all(is.na(bm_full$gene_biotype))) {
  loc_path <- file.path(dirname(in_tsv), "gene_locations.tsv")
  if (file.exists(loc_path)) {
    loc <- unique(fread(loc_path, select = c("external_gene_name", "gene_biotype"),
                        na.strings = c("", "NA")))
    loc <- loc[!is.na(external_gene_name) & external_gene_name != "" & !is.na(gene_biotype)]
    loc <- loc[!duplicated(external_gene_name)]
    bt_map <- setNames(loc$gene_biotype, loc$external_gene_name)
    bm_full[, gene_biotype := bt_map[external_gene_name]]
  }
}

# ---- Legacy position maps (autosomes 1-22; kept byte-identical) -------------
bm <- bm_full[chromosome_name %in% as.character(1:22)]
bm[, CHR := as.integer(chromosome_name)]
bm[, BP := (as.numeric(start_position) + as.numeric(end_position)) / 2]
bm <- bm[!is.na(CHR) & !is.na(BP)]

make_map <- function(dt, key_col) {
  d <- dt[!is.na(get(key_col)) & get(key_col) != ""]
  d <- d[, .(ID = get(key_col), CHR, BP)]
  d <- d[!duplicated(ID)]              # first occurrence wins
  as.data.frame(d)
}

# ---- Canonical gene table + resolver maps (full table) ----------------------
std <- c(as.character(1:22), "X", "Y")
g <- unique(bm_full[, .(ensembl_gene_id, external_gene_name, external_synonym,
                        gene_biotype, chromosome_name, start_position, end_position)])
g[, is_std := chromosome_name %in% std]
g[, chr_int := suppressWarnings(as.integer(chromosome_name))]   # NA for X/Y/patch
g[, chr_placed := !is.na(chr_int)]
g[, bp := (as.numeric(start_position) + as.numeric(end_position)) / 2]
g[, pc := !is.na(gene_biotype) & gene_biotype == "protein_coding"]

# One canonical row per ensembl id. symbol/biotype are constant per gene (the
# row explosion is only the synonym column), so pick the best-ranked contig row.
gene_rows <- unique(g[, .(ensembl_gene_id, external_gene_name, gene_biotype,
                          is_std, chr_placed, pc, chr_int, bp,
                          chromosome_name, start_position)])
setorder(gene_rows, ensembl_gene_id, -is_std, -chr_placed, -pc,
         chromosome_name, start_position)
canonical <- gene_rows[, .(symbol       = external_gene_name[1],
                           gene_biotype = gene_biotype[1],
                           CHR          = chr_int[1],
                           BP           = bp[1]),
                       by = ensembl_gene_id]

pick_one <- function(key_col) {
  d <- unique(g[!is.na(get(key_col)) & get(key_col) != "",
                .(key = get(key_col), ensembl_gene_id, is_std, chr_placed, pc)])
  setorder(d, key, -is_std, -chr_placed, -pc, ensembl_gene_id)
  d <- d[!duplicated(key)]
  setNames(d$ensembl_gene_id, d$key)
}

gene_positions <- list(
  by_symbol  = make_map(bm, "external_gene_name"),
  by_synonym = make_map(bm, "external_synonym"),
  by_ensembl = make_map(bm, "ensembl_gene_id"),
  canonical  = as.data.frame(canonical),
  sym2id     = pick_one("external_gene_name"),
  syn2id     = pick_one("external_synonym")
)

saveRDS(gene_positions, out_rds, compress = "xz")

cat("Wrote", out_rds, "\n")
cat("  by_symbol :", nrow(gene_positions$by_symbol), "genes\n")
cat("  by_synonym:", nrow(gene_positions$by_synonym), "aliases\n")
cat("  by_ensembl:", nrow(gene_positions$by_ensembl), "ensembl ids\n")
cat("  canonical :", nrow(gene_positions$canonical), "ensembl ids",
    if (all(is.na(canonical$gene_biotype))) "(no biotype in input)" else "(with biotype)", "\n")
cat("  sym2id    :", length(gene_positions$sym2id), "symbols\n")
cat("  syn2id    :", length(gene_positions$syn2id), "synonyms\n")
